import{mix}from './world.js';
export function initChronicle(s,fresh=false){if(s.chronicle?.version===1){s.chronicle.endingPage??=0;return;}const w=s.worldModel,o=w.origin,mother=o.mother;const litter=mother?Math.max(1,w.litter):null;const fatherKnown=fresh&&o.home==='family'&&mix(s.seed,701)%3===0;
s.chronicle={version:1,phase:fresh?'birth':s.alive?'living':'ending',birthAcknowledged:!fresh,endingSeen:false,endingPage:0,birthDate:null,legacy:!fresh,birth:{country:s.country.name,region:s.country.place,place:o.label,home:o.home,litterSize:litter,siblings:litter==null?null:litter-1,order:fresh&&litter?1+mix(s.seed,702)%litter:null,wards:mother?0:w.litter,mother:{id:'mother',known:mother,species:'개',breed:fresh&&mother?s.breed:null,ageYears:fresh&&mother?2+mix(s.seed,703)%5:null,features:fresh&&mother?s.appearance.lookId:null,alive:mother?true:null,together:mother},father:{id:'father',known:fatherKnown,species:fatherKnown?'개':null,breed:fatherKnown?s.breed:null,ageYears:fatherKnown?2+mix(s.seed,704)%6:null,features:fatherKnown?(mix(s.seed,706)%2?'황갈색 털':'짙은 갈색 털'):null,alive:fatherKnown?true:null,together:fatherKnown&&mix(s.seed,705)%2===0},health:fresh?s.health:null,body:'눈과 귀가 아직 열리지 않았고 혼자 걷지 못함',support:mother?'어미의 온기와 젖': '사람이 제공하는 보온과 먹이',risk:w.care<35?'돌봄이 드문 시간과 체온 유지':w.resource<35?'일정하지 않은 먹이 여건':'체온 유지와 꾸준한 초기 돌봄'},preferences:{pace:'story',pauseOnRecords:true},reading:null};}
export function setBirthDate(s,iso){if(!/^\d{4}-\d{2}-\d{2}$/.test(iso))throw Error('잘못된 출생 날짜');s.chronicle.birthDate=iso;s.worldModel.bornMonth=Number(iso.slice(5,7));}
export function dayDate(s,day=s.day){const iso=s.chronicle?.birthDate;if(!iso)return '날짜 미기록';const d=new Date(iso+'T00:00:00Z');d.setUTCDate(d.getUTCDate()+day);return d.toISOString().slice(0,10);}
export function ageText(d){return d<60?`생후 ${d}일`:d<365?`${Math.floor(d/30)}개월 ${d%30}일`:`${Math.floor(d/365)}년 ${Math.floor(d%365/30)}개월`}
export function birthStory(s){const b=s.chronicle.birth;return [`${b.country} · ${b.place}에서 태어났다.`,b.litterSize?`${b.litterSize}마리의 새끼 ${b.order?'중 '+b.order+'번째로':'중 하나로'} 세상에 왔다.`:b.wards?`이곳에는 함께 돌봄을 받는 작은 몸 ${b.wards}마리가 있다. 혈연 형제인지는 알 수 없다.`:'함께 태어난 형제의 수는 확인되지 않았다.',b.mother.together?'어미의 체온과 젖에 기대 몸을 붙인다.':'어미는 곁에 없다. 따뜻한 천과 돌보는 손길에 의지한다.','아직 눈을 뜨거나 혼자 걷지 못한다. 온기와 먹이를 받아들이며 첫날을 보낸다.'].join(' ');}
export function memoryTimeline(s){const ids=new Set(['birth','eyes','ears','walking','weaning','growing-body','maturity','adopt','moving','settled','reunion','companion-close','companion-parting','birthday','first-leash','first-name','litter-born','child-departure','child-reunion','aging','illness-onset','illness-recovered','clinical-symptom','clinical-diagnosis','surgery-performed','clinical-managed','rescued-shelter','guardian-changed','shelter-return','preventive-visit','shop-arrival','placement-visit','found-intake','identity-check','owner-unconfirmed','foster-start','foster-return','thread-result','thread-followup','thread-closed','journey-complete','journey-closed','death']);return s.log.filter(e=>ids.has(e.id)).map(e=>({...e}));}
export function biography(s){const b=s.chronicle.birth,lines=[`${b.country}의 ${b.place}에서 ${b.litterSize?b.litterSize+'마리의 새끼 중 하나로':'작은 몸으로'} 태어났다.`];if(s.log.some(e=>e.id==='nursing'))lines.push(b.mother.together?'어미 곁에서 젖을 먹고 잠들던 날들이 있었다.':'돌보는 손길에 기대 먹이를 받아먹고 잠들던 날들이 있었다.');if(s.log.some(e=>e.id==='walking'))lines.push('처음 발을 딛던 날을 지나 스스로 움직이는 범위가 넓어졌다.');if(s.log.some(e=>e.id==='adopt'))lines.push('새로운 사람을 만나 함께 사는 집으로 옮겨 갔다.');if(s.log.some(e=>e.id==='moving'))lines.push('낯선 집으로 옮겨 와 다시 물그릇과 잠자리의 위치를 익혔다.');if(s.log.some(e=>e.id==='companion-close'))lines.push('서로의 보폭과 숨소리에 익숙해진 동료가 있었다.');if(s.log.some(e=>e.id==='rescued-shelter'))lines.push('거리에서 사람의 도움을 받아 보호시설로 옮겨 간 날이 있었다.');if(s.log.some(e=>e.id==='foster-start'))lines.push('임시로 돌보는 사람의 집에서 쉬며 지낸 날들이 있었다.');if(s.log.some(e=>e.id==='reunion'))lines.push('떨어졌던 사람과 다시 만나 익숙한 잠자리로 돌아왔다.');if(s.log.some(e=>e.id==='guardian-changed'))lines.push('돌보는 사람이 바뀐 뒤 새로운 집의 생활을 익혔다.');if(s.log.some(e=>e.id==='surgery-performed'))lines.push('진료 뒤 수술을 받고 회복을 위한 시간을 보냈다.');if(s.log.some(e=>e.id==='clinical-managed'))lines.push('몸의 불편을 관리하며 지내는 날들이 기록에 남았다.');const born=s.log.filter(e=>e.id==='litter-born');if(born.length)lines.push(`${born.length}번 새끼들이 태어나는 날을 곁에서 맞았다.`);if(s.log.some(e=>e.id==='child-departure'))lines.push('자라난 새끼들과 떨어져 지내는 날도 찾아왔다.');for(const e of s.log.filter(e=>e.id==='journey-complete'&&['friend-history','guardian-anchor','mobility-memory'].includes(e.journeyKind)).slice(-3))lines.push(e.text);if(s.log.some(e=>e.id==='aging'))lines.push('쉬어 가는 시간이 길어졌지만 함께했던 날들은 기록에 남았다.');if(!s.alive)lines.push(`${ageText(s.day)}의 삶을 ${s.worldModel.context.label}에서 마쳤다. 기록된 원인은 ${s.cause||'확인되지 않음'}이다.`);return lines.join('\n\n');}
export function endingData(s){return {birth:s.chronicle.birth,deathDate:dayDate(s),age:ageText(s.day),place:`${s.country.name} · ${s.worldModel.context.label}`,cause:s.cause||'이전 기록에 원인이 남아 있지 않음',last:s.log.findLast?.(e=>e.id==='death')?.text||s.log.at(-1)?.text||'',memories:memoryTimeline(s),biography:biography(s),relations:s.relations.filter(r=>r.contacts>0).sort((a,b)=>b.trust-a.trust).slice(0,8)};}
export function validateChronicle(s){const c=s.chronicle;if(!c)return;if(c.version!==1||!['birth','living','ending'].includes(c.phase)||!c.birth||!c.preferences||!['story','observe'].includes(c.preferences.pace)||typeof c.birthAcknowledged!=='boolean'||!Array.isArray(s.log)||c.birthDate!==null&&!/^\d{4}-\d{2}-\d{2}$/.test(c.birthDate)||c.reading&&(typeof c.reading.id!=='string'||typeof c.reading.text!=='string'||!Number.isFinite(c.reading.minimumMs)))throw Error('손상된 생애 연출 기록');}
